def links_for(brand, language):
    """(terms_url, subscription_url) for brand+language, with graceful fallback:
    exact → brand+EN → wwiqtest+language → wwiqtest EN default."""
    b=(brand or "").lower(); L=(language or "EN").upper()
    for key in ((b,L),(b,"EN"),("wwiqtest",L),("wwiqtest","EN")):
        if key in REFUND_LEGAL_LINKS:
            return REFUND_LEGAL_LINKS[key]
    return (None, None)
